   179→                <div className="min-w-0 flex-1">
   180→                  <div className="font-black text-lg uppercase tracking-tight truncate">
   181→                    {t("player.soundcloud")}
   182→                  </div>
   183→                </div>
   184→                <a
   185→                  href={externalUrl}
   186→                  target="_blank"
   187→                  rel="noopener noreferrer"
   188→                  aria-label={tPlayer("controls.openOnSoundcloud")}
