   222→                  </div>
   223→
   224→                  <div className="min-w-0 flex-1">
   225→                    <div className="font-mono text-[10px] uppercase tracking-[0.2em] text-neo-accent">
   226→                      {statusLabel}
   227→                    </div>
   228→                    <div className="font-black uppercase tracking-tight text-neo-text truncate">
   229→                      {track?.title || tPlayer("status.noTrack")}
   230→                    </div>
   231→                    <div className="font-mono text-xs text-neo-text/60 truncate">
   232→                      {track?.artist || tPlayer("status.soundcloud")}
   233→                    </div>
   234→                  </div>
   235→
   236→                  <div className="flex items-center gap-2 flex-shrink-0">
   237→                    <button
   238→                      type="button"
   239→                      onClick={() => actions.previous()}
   240→                      disabled={controlsDisabled}
   241→                      aria-label={tPlayer("controls.previous")}
   242→                      className={cn(
   243→                        "h-11 w-11 border-2 border-neo-border bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
   244→                        "hover:-translate-y-0.5 transition-transform",
   245→                        "disabled:opacity-40 disabled:hover:translate-y-0 disabled:cursor-not-allowed"
   246→                      )}
   247→                    >
   248→                      <SkipBack className="w-5 h-5 mx-auto" />
   249→                    </button>
   250→
   251→                    <button
   252→                      type="button"
   253→                      onClick={() => actions.toggle()}
   254→                      aria-label={isPlaying ? tPlayer("controls.pause") : tPlayer("controls.play")}
   255→                      className={cn(
   256→                        "h-14 w-14 border-3 border-neo-border bg-neo-accent text-neo-text-inverse",
   257→                        "shadow-[5px_5px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 transition-transform"
   258→                      )}
   259→                    >
   260→                      {isPlaying ? (
   261→                        <Pause className="w-7 h-7 mx-auto" />
   262→                      ) : (
   263→                        <Play className="w-7 h-7 mx-auto translate-x-[1px]" />
   264→                      )}
   265→                    </button>
   266→
   267→                    <button
   268→                      type="button"
   269→                      onClick={() => actions.next()}
   270→                      disabled={controlsDisabled}
   271→                      aria-label={tPlayer("controls.next")}
   272→                      className={cn(
   273→                        "h-11 w-11 border-2 border-neo-border bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
   274→                        "hover:-translate-y-0.5 transition-transform",
   275→                        "disabled:opacity-40 disabled:hover:translate-y-0 disabled:cursor-not-allowed"
   276→                      )}
   277→                    >
   278→                      <SkipForward className="w-5 h-5 mx-auto" />
   279→                    </button>
   280→                  </div>
   281→                </div>
   282→
   283→                {/* Waveform */}
   284→                <div className="border-2 border-neo-border bg-neo-surface shadow-[6px_6px_0px_0px_var(--neo-shadow)] p-4">
   285→                  <SoundCloudWaveform
   286→                    samples={samples}
   287→                    progress={progress}
   288→                    disabled={controlsDisabled || durationMs <= 0}
   289→                    onSeek={(ratio) => actions.seekToRatio(ratio)}
   290→                    className={cn(isWaveformLoading && "opacity-80")}
   291→                    height={56}
   292→                  />
   293→                  <div className="mt-3 flex items-center justify-between font-mono text-[10px] uppercase tracking-[0.18em] text-neo-text/70">
   294→                    <span>{formatTime(positionMs)}</span>
   295→                    <div className="flex items-center gap-2">
   296→                      <div className="flex items-center gap-2 border-2 border-neo-border bg-neo-bg shadow-[3px_3px_0px_0px_var(--neo-shadow)] px-2 h-8">
   297→                        <button
   298→                          type="button"
   299→                          onClick={() => actions.setVolume(volume === 0 ? lastNonZeroVolume : 0)}
