   306→                            <VolumeX className="w-4 h-4" />
   307→                          ) : (
   308→                            <Volume2 className="w-4 h-4" />
   309→                          )}
   310→                        </button>
   311→                        <input
   312→                          type="range"
   313→                          min={0}
   314→                          max={100}
   315→                          value={volume}
   316→                          onChange={(e) => actions.setVolume(Number(e.target.value))}
   317→                          aria-label={tPlayer("controls.volume")}
   318→                          className="hidden md:block w-28 accent-neo-accent"
   319→                        />
   320→                      </div>
   321→                    </div>
   322→                    <span>
   323→                      -{formatTime(remainingMs)} / {formatTime(durationMs)}
   324→                    </span>
   325→                  </div>
