import { SOUND_CLOUD_PROFILE_URL, useGlobalAudioPlayer } from "@/lib/player/globalAudioPlayer";
import { useSoundCloudWaveform } from "@/lib/hooks/useSoundCloudWaveform";
import { ConsentGate } from "./legal/ConsentGate";
